import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';

const Dashboard = () => {
  const { user } = useSelector((state) => state.auth);
  const [showProfile, setShowProfile] = useState(false);
  const [isDark, setIsDark] = useState(false);
  const [battery, setBattery] = useState(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isListening, setIsListening] = useState(false);
  const [shakeEnabled, setShakeEnabled] = useState(true);
  const [lastShake, setLastShake] = useState(0);
  const [profileData, setProfileData] = useState({
    fullName: user?.fullName || '',
    email: user?.email || '',
    phone: user?.phone || ''
  });

  useEffect(() => {
    // Battery API
    if ('getBattery' in navigator) {
      navigator.getBattery().then(battery => {
        setBattery(Math.round(battery.level * 100));
        battery.addEventListener('levelchange', () => {
          setBattery(Math.round(battery.level * 100));
        });
      });
    }

    // Network status
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const theme = {
    bg: isDark ? '#000' : '#fff',
    cardBg: isDark ? '#1c1c1e' : '#fff',
    text: isDark ? '#fff' : '#000',
    subtext: isDark ? '#8e8e93' : '#666',
    border: isDark ? '#38383a' : '#f0f0f0',
    gradient: isDark ? 'linear-gradient(135deg, #1c1c1e 0%, #2c2c2e 100%)' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
  };

  const handleProfileUpdate = () => {
    alert('Profile updated successfully!');
    setShowProfile(false);
  };

  return (
    <div style={{ 
      background: theme.gradient,
      minHeight: '100vh',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
      margin: '0',
      padding: '0',
      maxWidth: '414px',
      marginLeft: 'auto',
      marginRight: 'auto',
      position: 'relative',
      boxShadow: isDark ? 'none' : '0 0 20px rgba(0,0,0,0.1)'
    }}>

      {/* Status Bar */}
      <div style={{
        background: isDark ? 'rgba(0,0,0,0.9)' : 'rgba(255,255,255,0.9)',
        backdropFilter: 'blur(20px)',
        padding: '8px 20px 5px 20px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        fontSize: '14px',
        fontWeight: '600',
        color: theme.text,
        borderBottom: `1px solid ${theme.border}`,
        position: 'sticky',
        top: '0',
        zIndex: '1000'
      }}>
        <div>9:41</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
          <span style={{ color: isOnline ? '#34c759' : '#ff3b30', fontSize: '12px' }}>
            {isOnline ? '●' : '●'} {isOnline ? 'Online' : 'Offline'}
          </span>
          {battery && (
            <span style={{ fontSize: '12px' }}>🔋{battery}%</span>
          )}
          <span>📶</span>
        </div>
      </div>

      {/* Header */}
      <div style={{
        background: isDark ? 'rgba(28,28,30,0.95)' : 'rgba(255,255,255,0.95)',
        backdropFilter: 'blur(20px)',
        padding: '20px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderBottom: `1px solid ${theme.border}`
      }}>
        <div>
          <h1 style={{ margin: '0', color: '#ff6b9d', fontSize: '28px', fontWeight: '700' }}>NIVRA</h1>
          <p style={{ margin: '2px 0 0 0', color: theme.subtext, fontSize: '14px' }}>
            Hi, {user?.fullName?.split(' ')[0] || 'User'}! 👋
          </p>
        </div>
        <div style={{ display: 'flex', gap: '10px' }}>
          <button 
            onClick={() => setIsDark(!isDark)}
            style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '8px 12px',
              fontSize: '16px',
              cursor: 'pointer'
            }}
          >
            {isDark ? '☀️' : '🌙'}
          </button>
          <button 
            onClick={() => setShowProfile(!showProfile)}
            style={{
              background: '#ff6b9d',
              color: 'white',
              border: 'none',
              borderRadius: '20px',
              padding: '8px 16px',
              fontSize: '14px',
              fontWeight: '500',
              cursor: 'pointer'
            }}
          >
            👤
          </button>
        </div>
      </div>

      {/* Content */}
      <div style={{ 
        padding: '20px',
        paddingBottom: '100px',
        background: theme.bg,
        minHeight: 'calc(100vh - 140px)'
      }}>

        {/* Profile Section */}
        {showProfile && (
          <div style={{
            background: theme.cardBg,
            border: `1px solid ${theme.border}`,
            borderRadius: '20px',
            padding: '20px',
            marginBottom: '20px',
            boxShadow: isDark ? 'none' : '0 10px 30px rgba(0,0,0,0.1)'
          }}>
            <h3 style={{ margin: '0 0 20px 0', color: theme.text, fontSize: '18px' }}>Edit Profile</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <input
                type="text"
                placeholder="Full Name"
                value={profileData.fullName}
                onChange={(e) => setProfileData({...profileData, fullName: e.target.value})}
                style={{
                  padding: '15px',
                  border: `2px solid ${theme.border}`,
                  borderRadius: '12px',
                  fontSize: '16px',
                  outline: 'none',
                  background: theme.bg,
                  color: theme.text
                }}
              />
              <input
                type="email"
                placeholder="Email"
                value={profileData.email}
                onChange={(e) => setProfileData({...profileData, email: e.target.value})}
                style={{
                  padding: '15px',
                  border: `2px solid ${theme.border}`,
                  borderRadius: '12px',
                  fontSize: '16px',
                  outline: 'none',
                  background: theme.bg,
                  color: theme.text
                }}
              />
              <input
                type="tel"
                placeholder="Phone"
                value={profileData.phone}
                onChange={(e) => setProfileData({...profileData, phone: e.target.value})}
                style={{
                  padding: '15px',
                  border: `2px solid ${theme.border}`,
                  borderRadius: '12px',
                  fontSize: '16px',
                  outline: 'none',
                  background: theme.bg,
                  color: theme.text
                }}
              />
              <div style={{ display: 'flex', gap: '10px' }}>
                <button 
                  onClick={handleProfileUpdate}
                  style={{
                    flex: '1',
                    background: '#667eea',
                    color: 'white',
                    border: 'none',
                    padding: '15px',
                    borderRadius: '12px',
                    fontSize: '16px',
                    fontWeight: '500',
                    cursor: 'pointer'
                  }}
                >
                  Save
                </button>
                <button 
                  onClick={() => setShowProfile(false)}
                  style={{
                    flex: '1',
                    background: theme.border,
                    color: theme.subtext,
                    border: 'none',
                    padding: '15px',
                    borderRadius: '12px',
                    fontSize: '16px',
                    cursor: 'pointer'
                  }}
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Emergency SOS */}
        <div style={{
          background: 'linear-gradient(135deg, #ff6b9d 0%, #c53975 100%)',
          borderRadius: '25px',
          padding: '40px 20px',
          textAlign: 'center',
          color: 'white',
          marginBottom: '25px',
          boxShadow: '0 15px 35px rgba(255, 107, 157, 0.3)'
        }}>
          <h2 style={{ margin: '0 0 20px 0', fontSize: '24px', fontWeight: '600' }}>🚨 Emergency SOS</h2>
          <button 
            onClick={() => {
              navigator.vibrate && navigator.vibrate([200, 100, 200]);
              alert('🚨 EMERGENCY ALERT SENT!\n\n📍 Location shared\n📞 Contacts notified\n🚔 Authorities alerted');
            }}
            style={{
              width: '120px',
              height: '120px',
              borderRadius: '50%',
              background: 'linear-gradient(135deg, #ff416c 0%, #ff4b2b 100%)',
              border: 'none',
              color: 'white',
              fontSize: '18px',
              fontWeight: 'bold',
              boxShadow: '0 10px 25px rgba(255, 65, 108, 0.4)',
              cursor: 'pointer',
              transition: 'transform 0.2s'
            }}
            onMouseDown={(e) => e.target.style.transform = 'scale(0.95)'}
            onMouseUp={(e) => e.target.style.transform = 'scale(1)'}
          >
            🆘<br/>SOS
          </button>
          <p style={{ margin: '20px 0 0 0', fontSize: '16px', opacity: '0.9' }}>
            Hold for 3 seconds for emergency
          </p>
        </div>

        {/* Quick Actions */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginBottom: '25px' }}>

          <div style={{
            background: theme.cardBg,
            border: `1px solid ${theme.border}`,
            borderRadius: '20px',
            padding: '20px',
            textAlign: 'center',
            boxShadow: isDark ? 'none' : '0 8px 25px rgba(0,0,0,0.08)',
            cursor: 'pointer'
          }}>
            <div style={{ fontSize: '32px', marginBottom: '12px' }}>🤖</div>
            <h4 style={{ margin: '0 0 8px 0', fontSize: '16px', color: theme.text, fontWeight: '600' }}>AI Chat</h4>
            <p style={{ margin: '0 0 15px 0', fontSize: '12px', color: theme.subtext }}>Safety guidance</p>
            <div style={{
              background: '#667eea',
              color: 'white',
              padding: '6px 12px',
              borderRadius: '15px',
              fontSize: '12px',
              fontWeight: '500'
            }}>
              Chat Now
            </div>
          </div>

          <div style={{
            background: theme.cardBg,
            border: `1px solid ${theme.border}`,
            borderRadius: '20px',
            padding: '20px',
            textAlign: 'center',
            boxShadow: isDark ? 'none' : '0 8px 25px rgba(0,0,0,0.08)',
            cursor: 'pointer'
          }}>
            <div style={{ fontSize: '32px', marginBottom: '12px' }}>📍</div>
            <h4 style={{ margin: '0 0 8px 0', fontSize: '16px', color: theme.text, fontWeight: '600' }}>Location</h4>
            <p style={{ margin: '0 0 15px 0', fontSize: '12px', color: theme.subtext }}>Track & share</p>
            <div style={{
              background: '#28a745',
              color: 'white',
              padding: '6px 12px',
              borderRadius: '15px',
              fontSize: '12px',
              fontWeight: '500'
            }}>
              Active
            </div>
          </div>

          <div style={{
            background: theme.cardBg,
            border: `1px solid ${theme.border}`,
            borderRadius: '20px',
            padding: '20px',
            textAlign: 'center',
            boxShadow: isDark ? 'none' : '0 8px 25px rgba(0,0,0,0.08)',
            cursor: 'pointer'
          }}>
            <div style={{ fontSize: '32px', marginBottom: '12px' }}>📞</div>
            <h4 style={{ margin: '0 0 8px 0', fontSize: '16px', color: theme.text, fontWeight: '600' }}>Contacts</h4>
            <p style={{ margin: '0 0 15px 0', fontSize: '12px', color: theme.subtext }}>Emergency list</p>
            <div style={{
              background: '#fd7e14',
              color: 'white',
              padding: '6px 12px',
              borderRadius: '15px',
              fontSize: '12px',
              fontWeight: '500'
            }}>
              Manage
            </div>
          </div>

          <div style={{
            background: theme.cardBg,
            border: `1px solid ${theme.border}`,
            borderRadius: '20px',
            padding: '20px',
            textAlign: 'center',
            boxShadow: isDark ? 'none' : '0 8px 25px rgba(0,0,0,0.08)',
            cursor: 'pointer'
          }}>
            <div style={{ fontSize: '32px', marginBottom: '12px' }}>📋</div>
            <h4 style={{ margin: '0 0 8px 0', fontSize: '16px', color: theme.text, fontWeight: '600' }}>History</h4>
            <p style={{ margin: '0 0 15px 0', fontSize: '12px', color: theme.subtext }}>Past alerts</p>
            <div style={{
              background: '#6f42c1',
              color: 'white',
              padding: '6px 12px',
              borderRadius: '15px',
              fontSize: '12px',
              fontWeight: '500'
            }}>
              View All
            </div>
          </div>
        </div>

        {/* Safety Tips */}
        <div style={{
          background: theme.cardBg,
          border: `1px solid ${theme.border}`,
          borderRadius: '20px',
          padding: '20px',
          boxShadow: isDark ? 'none' : '0 8px 25px rgba(0,0,0,0.08)'
        }}>
          <h3 style={{ margin: '0 0 15px 0', fontSize: '18px', color: theme.text, fontWeight: '600' }}>
            💡 Safety Tips
          </h3>
          <div style={{ fontSize: '14px', lineHeight: '1.8', color: theme.subtext }}>
            <p style={{ margin: '0 0 8px 0' }}>🔹 Share location with trusted contacts</p>
            <p style={{ margin: '0 0 8px 0' }}>🔹 Trust your instincts always</p>
            <p style={{ margin: '0 0 8px 0' }}>🔹 Keep phone charged</p>
            <p style={{ margin: '0 0 8px 0' }}>🔹 Use well-lit routes</p>
            <p style={{ margin: '0' }}>🔹 Know emergency numbers</p>
          </div>
        </div>
      </div>

      {/* Bottom Navigation */}
      <div style={{
        position: 'fixed',
        bottom: '0',
        left: '50%',
        transform: 'translateX(-50%)',
        width: '100%',
        maxWidth: '414px',
        background: isDark ? 'rgba(28,28,30,0.95)' : 'rgba(255,255,255,0.95)',
        backdropFilter: 'blur(20px)',
        borderTop: `1px solid ${theme.border}`,
        padding: '10px 0 25px 0',
        display: 'flex',
        justifyContent: 'space-around',
        alignItems: 'center'
      }}>
        <button style={{ background: 'none', border: 'none', padding: '10px', fontSize: '24px', cursor: 'pointer' }}>🏠</button>
        <button style={{ background: 'none', border: 'none', padding: '10px', fontSize: '24px', cursor: 'pointer' }}>🤖</button>
        <button style={{ background: 'none', border: 'none', padding: '10px', fontSize: '24px', cursor: 'pointer' }}>📍</button>
        <button style={{ background: 'none', border: 'none', padding: '10px', fontSize: '24px', cursor: 'pointer' }}>⚙️</button>
      </div>
    </div>
  );
};

export default Dashboard;
